{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The aws_instance.web resource does not have encryption enabled for its Elastic Block Store (EBS) volumes, potentially exposing stored data."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The aws_instance.web resource does not explicitly disable Instance Metadata Service Version 1 (IMDSv1), potentially allowing insecure metadata access."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The aws_instance.web resource does not have an IAM role attached, potentially limiting its ability to securely access AWS resources."
    }
  ],
  "patched_code": "resource "aws_instance" "web" {
  ami                    = "${var.ami}"
  instance_type          = "t2.micro"
  subnet_id              = "${aws_subnet.public-subnet.id}"
  vpc_security_group_ids = ["${aws_security_group.sgweb.id}"]
  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }
  root_block_device {
    encrypted = true
  }
  iam_instance_profile = "${aws_iam_instance_profile.example.name}"
}

resource "aws_iam_instance_profile" "example" {
  name = "example-profile"
  role = "${aws_iam_role.example.name}"
}

resource "aws_iam_role" "example" {
  name        = "example-role"
  description = "An example IAM role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}",
  "fix_summary": "Enabled EBS encryption, disabled IMDSv1 by requiring IMDSv2 tokens, and attached an IAM role to the EC2 instance."
}
